from pathlib import Path

ES_CARD='''\n<a class="card reveal" data-cat="education ai" href="/es/tethered/habilidades-digitales-ia/"><div class="visual"><img src="/images/vista-aerea.png" alt="Encuesta de Habilidades Digitales y Uso de IA"></div><div class="body"><div class="meta"><span>Tether Education × ConsiliumBots</span><span>2025</span></div><h3>Habilidades Digitales y Uso de IA</h3><p>Diagnóstico sobre habilidades digitales y uso de IA en 12.928 estudiantes de educación pública.</p><div class="impact"><span>12.928 estudiantes</span><span>72 escuelas</span><span>IA</span><span>Educación pública</span></div><span class="cta">Ver proyecto ↗</span></div></a>'''
EN_CARD='''\n<a class="card reveal" data-cat="education ai" href="/tethered/digital-skills-ai-survey/"><div class="visual"><img src="/images/vista-aerea.png" alt="Digital Skills and AI Use Survey"></div><div class="body"><div class="meta"><span>Tether Education × ConsiliumBots</span><span>2025</span></div><h3>Digital Skills & AI Use</h3><p>A diagnostic study of digital skills and AI use across 12,928 public-school students.</p><div class="impact"><span>12,928 students</span><span>72 schools</span><span>AI</span><span>Public education</span></div><span class="cta">View project ↗</span></div></a>'''

for rel, card, marker in [
    ('es/projects.html', ES_CARD, '/es/tethered/habilidades-digitales-ia/'),
    ('projects.html', EN_CARD, '/tethered/digital-skills-ai-survey/'),
]:
    p=Path(rel)
    s=p.read_text(encoding='utf-8')
    if marker not in s:
        anchor='<a class="card reveal" data-cat="education ai product" href="/es/tethered/tether-studio">' if rel.startswith('es/') else '<a class="card reveal" data-cat="education ai product" href="/tethered/tether-studio">'
        s=s.replace(anchor, card+'\n'+anchor, 1)
        p.write_text(s, encoding='utf-8')

