def nav(es):
    if es:
        return '<header class="nav"><a class="brand" href="/es/">Felipe Quiroz</a><div class="nav-right"><nav class="nav-center"><a href="/es/#work">Trabajo</a><a href="/es/about">Sobre mí</a><a class="active" href="/es/projects">Proyectos</a><a href="/es/initiatives">Iniciativas</a><a href="/es/blog">Blog</a></nav><a class="lang" href="/tethered/digital-skills-ai-survey/">EN</a></div></header>'
    return '<header class="nav"><a class="brand" href="/">Felipe Quiroz</a><div class="nav-right"><nav class="nav-center"><a href="/#work">Work</a><a href="/about">About</a><a class="active" href="/projects">Projects</a><a href="/initiatives">Initiatives</a><a href="/blog">Blog</a></nav><a class="lang" href="/es/tethered/habilidades-digitales-ia/">ES</a></div></header>'

