def page(es=False):
    lang='es' if es else 'en'
    title='Encuesta de Habilidades Digitales y Uso de IA' if es else 'Digital Skills and AI Use Survey'
    desc=('Un diagnóstico 2025 sobre habilidades digitales y uso de IA en 12.928 estudiantes de 72 escuelas públicas del SLEP del Pino.' if es else 'A 2025 diagnostic study of digital skills and AI use among 12,928 students across 72 public schools with SLEP del Pino.')
    h1=('Entender cómo los estudiantes navegan un mundo digital.' if es else 'Understanding how students navigate a digital world.')
    project=('El diagnóstico estudió habilidades digitales y uso de IA desde cuarto básico hasta cuarto medio, conectando investigación, implementación en escuelas y reportes a nivel de establecimiento.' if es else 'The diagnostic studied digital skills and AI use from fourth grade through the end of secondary school, connecting research, school implementation and school-level reporting.')
    evidence=('Evidencia para orientar la educación digital.' if es else 'Evidence to guide digital education.')
    body=('La encuesta examinó cómo los estudiantes acceden a tecnología, usan herramientas de IA, evalúan sus respuestas y qué apoyo esperan de sus colegios. El trabajo se desarrolló con SLEP del Pino en San Bernardo, El Bosque, La Pintana y Calera de Tango.' if es else 'The survey examined how students access technology, use AI tools, evaluate their answers and what support they want from schools. The work was carried out with SLEP del Pino in San Bernardo, El Bosque, La Pintana and Calera de Tango.')
    labels=[('Acceso digital','Entender la tecnología disponible para los estudiantes y las condiciones en que la usan.') if es else ('Digital access','Understand the technology available to students and the conditions in which they use it.'),('Habilidades y uso de IA','Medir habilidades digitales reportadas y la experiencia de los estudiantes con herramientas de IA.') if es else ('Skills and AI use','Measure reported digital skills and students’ experience with AI tools.'),('Reportes por escuela','Organizar la evidencia en reportes para establecimientos y para la red escolar.') if es else ('School-level reporting','Organize the evidence into reports for individual schools and the wider school network.')]
    cards=''.join(f'<article class="card"><span>0{i}</span><h3>{a}</h3><p>{b}</p></article>' for i,(a,b) in enumerate(labels,1))
    role='Partnerships & implementation' if not es else 'Partnerships & implementación'
    return f'''<!doctype html><html lang="{lang}"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{title} | Felipe Quiroz</title><meta name="description" content="{desc}"><link rel="icon" href="/favicon.png"><link rel="preconnect" href="https://fonts.googleapis.com"><link rel="preconnect" href="https://fonts.gstatic.com" crossorigin><link href="https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600&family=Manrope:wght@400;500;600&display=swap" rel="stylesheet"><style>{STYLE}</style></head><body>{nav(es)}<main><section class="hero"><div class="shell"><div class="hero-top"><div class="lockup">Tether Education × ConsiliumBots</div><div class="hero-meta"><span>{'Medición' if es else 'Measurement'}</span><span>{'Educación pública' if es else 'Public education'}</span><span>Chile · 2025</span></div></div><h1>{h1}</h1><div class="hero-bottom"><div><p class="hero-copy">{desc}</p><div class="hero-actions"><a class="button" href="https://habilidades-digitales.encuesta.ai/#top" target="_blank" rel="noopener noreferrer">{'Explorar resultados ↗' if es else 'Explore survey results ↗'}</a></div></div><div class="role-box"><strong>{role}</strong><span>Tether Education<br>SLEP del Pino · Chile</span></div></div></div></section><section class="stats"><div class="shell stats-grid"><div class="stat"><strong>12.928</strong><span>{'estudiantes' if es else 'students'}</span></div><div class="stat"><strong>72</strong><span>{'escuelas públicas' if es else 'public schools'}</span></div><div class="stat"><strong>4</strong><span>{'comunas' if es else 'municipalities'}</span></div><div class="stat"><strong>2025</strong><span>{'diagnóstico y reporting' if es else 'diagnostic & reporting'}</span></div></div></section><section class="section"><div class="shell two-col"><div><div class="kicker">{'El proyecto' if es else 'The project'}</div></div><div><h2>{evidence}</h2><p>{project}</p><p>{body}</p><div class="cards">{cards}</div></div></div></section><section class="media-wrap"><div class="media-grid"><figure class="media"><img src="/images/vista-aula.png" alt="{'Implementación de la encuesta en aula' if es else 'Survey implementation in the classroom'}"></figure><figure class="media"><img src="/images/vista-pc.png" alt="{'Estudiante respondiendo la encuesta digital' if es else 'Student completing the digital survey'}"></figure></div></section><section class="section soft"><div class="shell two-col"><div><div class="kicker">{'Investigación e implementación' if es else 'Research & implementation'}</div></div><div><h2>{'Un diagnóstico 2025 conectado a una agenda de investigación más amplia.' if es else 'A 2025 diagnostic connected to a wider research agenda.'}</h2><p>{'Los resultados públicos corresponden al estudio realizado en Santiago. El proyecto también abrió una línea de trabajo para futuras mediciones y colaboración con escuelas y partners de investigación en otros mercados.' if es else 'The public results cover the Santiago study. The project also opened a path for future measurement waves and collaboration with schools and research partners in other markets.'}</p><div class="hero-actions"><a class="button secondary" href="https://habilidades-digitales.encuesta.ai/#top" target="_blank" rel="noopener noreferrer">{'Ver sitio de resultados ↗' if es else 'View results site ↗'}</a></div></div></div></section><section class="closing"><div class="shell closing-inner"><div><h2>{'Ver la evidencia completa.' if es else 'Explore the full evidence.'}</h2><p>{'Resultados públicos de la Encuesta de Habilidades Digitales y Uso de IA 2025.' if es else 'Public results from the 2025 Digital Skills and AI Use Survey.'}</p></div><a href="https://habilidades-digitales.encuesta.ai/#top" target="_blank" rel="noopener noreferrer">{'Explorar resultados ↗' if es else 'Explore results ↗'}</a></div></section></main>{footer(es)}<script src="/mobile-nav.js" defer></script></body></html>'''

Path('es/tethered/habilidades-digitales-ia').mkdir(parents=True,exist_ok=True)
Path('tethered/digital-skills-ai-survey').mkdir(parents=True,exist_ok=True)
Path('es/tethered/habilidades-digitales-ia/index.html').write_text(page(True),encoding='utf-8')
Path('tethered/digital-skills-ai-survey/index.html').write_text(page(False),encoding='utf-8')
